{
  "references": [
    {
      "id": "R1",
      "summary_ko": "채소들이 그릇에 떨어지지만 샐러드가 되지 않음."
    },
    {
      "id": "R2",
      "summary_ko": "채소의 정체가 매우 불분명하고 썰린 조각들이 지나치게 길고 비현실적이며 양상추만 식별 가능함."
    }
  ],
  "candidates": [
    {
      "id": "C1",
      "summary_ko": "영상 특징과 픽셀 구조가 함께 변하여 형태 및 존재 변화 가능성이 감지된 미식별 영역."
    },
    {
      "id": "C2",
      "summary_ko": "공중에 떠 있는 채소 뒤로 요리사의 머리와 목이 사라진 후 일관되게 다시 나타나지 않음."
    },
    {
      "id": "C3",
      "summary_ko": "채소 뭉치가 그릇에 떨어지기 전 공중에 부자연스럽게 떠 있으며 내부 색상 띠가 변형됨."
    }
  ],
  "pairs": [
    {
      "reference_id": "R1",
      "candidate_id": "C1",
      "verdict": "uncertain",
      "reason_ko": "후보 C1은 대상이 식별되지 않은 일반적인 측정 제안으로, 채소가 그릇에 떨어지는 과정의 이상 현상과 관련이 있을 수 있으나 텍스트만으로는 동일 여부를 확정할 수 없음."
    },
    {
      "reference_id": "R1",
      "candidate_id": "C2",
      "verdict": "different",
      "reason_ko": "참조 R1은 채소들이 샐러드가 되지 않는다는 내용인 반면 후보 C2는 요리사의 머리와 목이 사라지는 결함에 집중하고 있어 대상과 결함이 다름."
    },
    {
      "reference_id": "R1",
      "candidate_id": "C3",
      "verdict": "different",
      "reason_ko": "참조 R1은 채소가 떨어져 샐러드가 되지 않는 현상을 설명하는 반면, 후보 C3은 채소 뭉치가 공중에 떠서 내부가 변형되는 현상에 중점을 두어 서로 다름."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C1",
      "verdict": "uncertain",
      "reason_ko": "후보 C1은 형태나 존재 변화 가능성을 언급하는 일반 측정 제안으로, 비현실적인 채소 형태와 연관될 가능성이 있으나 특정 대상이 없어 확정할 수 없음."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C2",
      "verdict": "different",
      "reason_ko": "참조 R2는 채소 자체의 비현실적인 형태와 식별 불가능성에 관한 것이며, 후보 C2는 요리사의 머리와 목의 사라짐에 관한 것으로 서로 다른 결함임."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C3",
      "verdict": "different",
      "reason_ko": "참조 R2는 채소 조각이 너무 길고 비현실적이라는 형태적 설명인 반면, 후보 C3은 공중 부양 및 색상 띠 변형 현상을 설명하고 있어 결함 내용이 다름."
    }
  ]
}
